import re

_TITLE_RE = re.compile(
    r"<title>(.*?)</title>",
    re.IGNORECASE | re.DOTALL | re.ASCII,
)


def title_of(html: str) -> str:
    """Return the text between `<title>` and `</title>` in `html`.

    Tags match case-insensitively. Only the first `<title>` is used, and
    its content ends at the first `</title>` after it. The text is returned
    exactly as written: no whitespace stripping, no entity unescaping.
    Returns "" if there is no `<title>` or it is never closed.
    Does not use the network; `html` is already fetched.
    """
    m = _TITLE_RE.search(html)
    if m is None:
        return ""
    return m.group(1)


def test_basic_title() -> None:
    html = "<html><head><title>Hello</title></head><body></body></html>"
    assert title_of(html) == "Hello"


def test_no_title() -> None:
    assert title_of("<html><body>No title here</body></html>") == ""
    assert title_of("") == ""


def test_empty_title() -> None:
    assert title_of("<title></title>") == ""


def test_unclosed_title() -> None:
    assert title_of("<html><title>Dangling") == ""


def test_case_insensitive_tags() -> None:
    assert title_of("<HTML><TITLE>Upper</TITLE></HTML>") == "Upper"
    assert title_of("<Title>Mixed</tItLe>") == "Mixed"


def test_whitespace_preserved() -> None:
    assert title_of("<title>  spaced out \n</title>") == "  spaced out \n"


def test_multiline_title() -> None:
    assert title_of("<title>line one\nline two</title>") == "line one\nline two"


def test_first_title_wins() -> None:
    assert title_of("<title>first</title><title>second</title>") == "first"


def test_stray_closing_tag_before_open() -> None:
    assert title_of("</title><title>a</title>") == "a"


def test_only_closing_tag() -> None:
    assert title_of("oops</title>") == ""


def test_entities_not_unescaped() -> None:
    assert title_of("<title>Tom &amp; Jerry</title>") == "Tom &amp; Jerry"
